#!/usr/bin/env python3
"""Chiikawa ASCII dance. Python 3; no dependencies.

Run: python chiikawa_dance.py --width 240
Options: --width 100 --speed 1.5 --once
Stop with Ctrl+C. For detail, maximize the terminal and shrink its font, then use --width 240 or --width 320.
The original 71-frame animation and timings are embedded in this file.
"""
import argparse
import base64
import json
import os
import shutil
import sys
import time
import zlib

DATA = ''


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--width', type=int, choices=[48,64,80,100,120,160,200,240,320], help='ASCII columns; defaults to a size that fits your terminal')
    parser.add_argument('--speed', type=float, default=1.0, help='Playback speed multiplier (default: 1)')
    parser.add_argument('--once', action='store_true', help='Play once instead of looping')
    parser.add_argument('--frame', type=int, help='Print one still frame (0-70) and exit')
    args = parser.parse_args()
    if args.speed <= 0:
        parser.error('--speed must be greater than zero')
    variants = json.loads(zlib.decompress(base64.b64decode(DATA)))
    cols, rows = shutil.get_terminal_size((100,30))
    fits = [int(w) for w,f in variants.items() if int(w) < cols and f[0][0].count('\n')+2 < rows]
    width = args.width or max(fits, default=48)
    frames = variants[str(width)]
    if args.frame is not None:
        if not 0 <= args.frame < len(frames):
            parser.error('--frame must be between 0 and 70')
        print(frames[args.frame][0])
        return
    # Windows 10/11: enable ANSI escape sequences in the console.
    if os.name == 'nt':
        import ctypes
        kernel = ctypes.windll.kernel32
        handle = kernel.GetStdHandle(-11)
        mode = ctypes.c_ulong()
        if kernel.GetConsoleMode(handle, ctypes.byref(mode)):
            kernel.SetConsoleMode(handle, mode.value | 4)
    if not sys.stdout.isatty():
        parser.error('Run this in a terminal, or use --frame 0 to print a still image.')
    sys.stdout.write('\x1b[?1049h\x1b[?25l\x1b[2J')
    try:
        while True:
            for frame, duration in frames:
                started = time.monotonic()
                sys.stdout.write('\x1b[H' + frame.replace('\n', '\r\n'))
                sys.stdout.flush()
                time.sleep(max(0, duration/args.speed - (time.monotonic()-started)))
            if args.once:
                break
    except KeyboardInterrupt:
        pass
    finally:
        sys.stdout.write('\x1b[?25h\x1b[?1049l')
        sys.stdout.flush()


if __name__ == '__main__':
    main()
